FConvexHalfEdgeStructureDataS16 MakeBoxStructureData()
{
	// NOTE: planes vertices are counter-clockwise when looking at the face from outside 
	// the box in the diagram above. Plane order defined by SNormals.
	TArray<TArray<int32>> PlaneVertices
	{
		{ 0, 4, 6, 2 },	// -X,
		{ 0, 1, 5, 4 },	// -Y
		{ 0, 2, 3, 1 },	// -Z
		{ 1, 3, 7, 5 },	//  X
		{ 2, 6, 7, 3 },	//  Y
		{ 4, 5, 7, 6 },	//  Z
	};

	return FConvexHalfEdgeStructureDataS16::MakePlaneVertices(PlaneVertices, 8);
}

// NOTE: Plane order must match order implied by TAABB::GetIndex/GetVertex
// i.e., negative pointing normals first
template<typename T, int D> TArray<FVec3> TBox<T, D>::SNormals =
{
	FVec3(-1, 0, 0),	// -X
	FVec3( 0,-1, 0),	// -Y
	FVec3( 0, 0,-1),	// -Z
	FVec3( 1, 0, 0),	//  X
	FVec3( 0, 1, 0),	//  Y
	FVec3( 0, 0, 1),	//  Z
};

// NOTE: Vertex order must match order implied by TAABB::GetIndex/GetVertex
template<typename T, int D> TArray<FVec3> TBox<T, D>::SVertices =
{
	FVec3(-1,-1,-1),	// 0 
	FVec3( 1,-1,-1),	// 1 
	FVec3(-1, 1,-1),	// 2 
	FVec3( 1, 1,-1),	// 3 
	FVec3(-1,-1, 1),	// 4 
	FVec3( 1,-1, 1),	// 5 
	FVec3(-1, 1, 1),	// 6 
	FVec3( 1, 1, 1),	// 7 
};

}

// The number of vertices that make up the corners of the specified face
int32 NumPlaneVertices(int32 PlaneIndex) const
{
	return SStructureData.NumPlaneVertices(PlaneIndex);
}

// Get the vertex index of one of the vertices making up the corners of the specified face
int32 GetPlaneVertex(int32 PlaneIndex, int32 PlaneVertexIndex) const
{
	return SStructureData.GetPlaneVertex(PlaneIndex, PlaneVertexIndex);
}

// Get the vertex at the specified index (e.g., indices from GetPlaneVertexs)
const FVec3 GetVertex(int32 VertexIndex) const
{
	const FVec3& Vertex = SVertices[VertexIndex];
	return AABB.Center() + 0.5f * (Vertex * AABB.Extents());
}

